import clsx from 'clsx';
import { AnimatePresence, motion, Variants } from 'framer-motion';
import React, { forwardRef, useContext } from 'react';

import AnimationsJS from '@dynatrace/strato-design-tokens/animations-js';

import {
  accordionContentCSS,
  accordionContentWrapperCSS,
} from './Accordion.sty.js';
import { AccordionSectionContext } from './contexts/AccordionSectionContext.js';
import type { DataTestId } from '../../core/types/data-props.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import type { WithChildren } from '../../core/types/with-children.js';
import { _isStringChildren } from '../../core/utils/is-string-children.js';
import { Text } from '../../typography/Text.js';

export type AccordionSectionContentProps = WithChildren &
  StylingProps &
  DataTestId;

//variant for accordion section expand and collapse animation
const animationVariantSectionContent: Variants = {
  expanded: {
    height: 'auto',
    opacity: 1,
    transition: {
      duration: AnimationsJS.ExpandCollapse.Duration.Base,
      ease: AnimationsJS.ExpandCollapse.Easing,
    },
  },
  collapsed: {
    height: 0,
    opacity: 0,
    transition: {
      duration: AnimationsJS.ExpandCollapse.Duration.Base,
      ease: AnimationsJS.ExpandCollapse.Easing,
    },
  },
};
// #endregion

/** Accordion Section Content component */
export const AccordionSectionContent = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  AccordionSectionContentProps
>((props, forwardedRef) => {
  const {
    children,
    className: consumerClassName,
    style: consumerStyle,
    'data-testid': dataTestId,
  }: AccordionSectionContentProps = props;
  const { triggerId, contentId, isExpanded, keepMounted, size } = useContext(
    AccordionSectionContext,
  );
  const childIsText = _isStringChildren(children);

  const content = (
    <motion.div
      className={accordionContentWrapperCSS}
      variants={animationVariantSectionContent}
      initial="collapsed"
      animate={isExpanded ? 'expanded' : 'collapsed'}
      exit="collapsed"
    >
      <div
        className={clsx([
          accordionContentCSS({
            size,
          }),
          consumerClassName,
        ])}
        data-testid={dataTestId}
        ref={forwardedRef}
        id={contentId}
        role="region"
        aria-labelledby={triggerId}
        style={consumerStyle}
      >
        {childIsText ? (
          <Text textStyle="base" as="p">
            {children}
          </Text>
        ) : (
          children
        )}
      </div>
    </motion.div>
  );

  if (keepMounted) {
    return content;
  }

  return <AnimatePresence>{isExpanded && content}</AnimatePresence>;
});

(
  AccordionSectionContent as typeof AccordionSectionContent & {
    displayName: string;
  }
).displayName = 'Accordion.SectionContent';
